import math

def create_playlist(name: str) -> str:
    playlists_url = "https://api.spotify.com/v1/me/playlists/"

    payload = {
    "name": "EVERYTHING",
    "description": "Playlist with everything. Generated by https://github.com/Parkman145/Everything-Playlist"
    }

    headers = {
    "Content-Type": "application/json",
    "User-Agent": "python",
    "Authorization": f"Bearer {token}"
    }

    response = requests.request("POST", playlists_url, json=payload, headers=headers)
    body = json.loads(response.content)


    id = body["id"]

    return id

# Holy name
def get_song_ids_and_album_urls_from_playlist(playlist_id):
    global error_song_count
    song_ids = set()
    large_album_images = set()
    medium_album_images = set()
    small_album_images = set()

    current_playlist_items_url = f"https://api.spotify.com/v1/playlists/{playlist_id}/items"
    headers = {
    "Content-Type": "application/json",
    "User-Agent": "python",
    "Authorization": f"Bearer {token}"
    }
    
    while True:
        print(f"current playlist url {current_playlist_items_url}")
        items_response = json.loads(requests.request("GET", current_playlist_items_url, headers=headers).content)
        
        

        for song in items_response["items"]:
            song_id = song.get("item").get("id")
            if (not song_id):
                error_song_count += 1
                continue

            large_album_image, medium_album_image, small_album_image = song.get("item").get("album").get("images")

            song_ids.add(song_id)
            large_album_images.add(large_album_image.get("url"))
            medium_album_images.add(medium_album_image.get("url"))
            small_album_images.add(small_album_image.get("url"))
    
        if items_response["next"]:
            current_playlist_items_url = items_response["next"]
        else: break

    
    return (song_ids, large_album_images, medium_album_images, small_album_images)


token = auth.get_token()


requests_cache.install_cache('demo_cache', expire_after=3600, ignored_parameters=[])


# Setup Config
with open("config.json") as f:
    config = json.load(f) 

exclude_other_users = config["exclude"]["exclude_other_users"]
exclude_playlists = config["exclude"]["playlists"]
exclude_songs = config["exclude"]["songs"]
whitelist = config["exclude"]["whitelist"]

headers = {
    "User-Agent": "Python",
    "Authorization": f"Bearer {token}"
}

me_uri = json.loads(requests.request("GET", "https://api.spotify.com/v1/me", headers=headers).text)["uri"]




seen_albums = set()
seen_songs = set()
song_uris = []


playlists_counter = 0
error_song_count = 0


if __name__ == "__main__":
    EVERYTHING_playlist_id = create_playlist("EVERYTHING")

    current_playlists_url = "https://api.spotify.com/v1/me/playlists/"

    headers = {
        "Content-Type": "application/json",
        "User-Agent": "python",
        "Authorization": f"Bearer {token}"
    }
    song_ids = set()
    large_album_images = set()
    medium_album_images = set()
    small_album_images = set()

    while True:
        response = requests.request("GET", current_playlists_url, headers=headers)
        playlists = json.loads(response.text)
        total_playlists = playlists["total"]

        for playlist in playlists["items"]:
            playlists_counter += 1
            print(f"\rPlaylists Checked: {playlists_counter}/{total_playlists}, Error with {error_song_count} songs                     ", end="")
            if (playlist["id"] in exclude_playlists or playlist["name"] in exclude_playlists) ^ whitelist:
                continue
            if exclude_other_users and (playlist["owner"]["uri"] != me_uri):
                continue

            playlist_song_ids, playlist_large_album_images, playlist_medium_album_images, playlist_small_album_images = get_song_ids_and_album_urls_from_playlist(playlist["id"])
            
            song_ids.update(playlist_song_ids)
            large_album_images.update(playlist_large_album_images)
            medium_album_images.update(playlist_medium_album_images)
            small_album_images.update(playlist_small_album_images)
            

        if playlists["next"]:
            current_playlists_url = playlists["next"]
        else: break
    
    print(song_ids)

    song_uris = [f"spotify:track:{id}" for id in song_ids]

    url = f"https://api.spotify.com/v1/playlists/{EVERYTHING_playlist_id}/items"
    while song_uris:

        payload = {"uris": song_uris[:100]}
        headers = {
            "Content-Type": "application/json",
            "User-Agent": "Python",
            "Authorization": f"Bearer {token}"
        }

        response = requests.request("POST", url, json=payload, headers=headers)

        if response.status_code == 429:
            sleep(1)
            continue

        song_uris = song_uris[100:]
